style.css:
@-moz-document domain("youtube.com") {
/* 1. FONDO REFORZADO: Rojo con Puntos Blancos Pequeños (Fijo y obligatorio) */
    html, body, ytd-app, ytd-page-manager, #page-manager, #content, #columns,
    #background, #masthead-container, tp-yt-app-drawer, ytd-browse, 
    #contentContainer, ytd-mini-guide-renderer, #contentContainer.tp-yt-app-drawer {
        background-color: #E60023 !important;
        background-image: radial-gradient(#FFFFFF 12%, transparent 12%),
                          radial-gradient(#FFFFFF 12%, transparent 12%) !important;
        background-size: 24px 24px !important;
        background-position: 0 0, 12px 12px !important;
        background-attachment: fixed !important;
    }

    /* Rompemos CUALQUIER capa oscura o gris de YouTube que esté tapando tus puntitos */
    ytd-rich-grid-renderer, ytd-watch-flexy, #columns.ytd-watch-flexy,
    #page-manager.ytd-app, ytd-playlist-video-list-renderer,
    ytd-section-list-renderer, #contents.ytd-section-list-renderer,
    #primary.ytd-watch-flexy, #secondary.ytd-watch-flexy,
    ytd-guide-renderer, #sections.ytd-guide-renderer, ytd-item-section-renderer,
    ytd-rich-item-renderer, #content-sidebar, ytd-compact-video-renderer {
        background: transparent !important;
        background-color: transparent !important;
    }

    /* 2. TU BARRA DE BÚSQUEDA SUPERIOR: Amarillo Claro */
    #search-form, 
    #container.ytd-searchbox, 
    input#search,
    .ytd-searchbox {
        background-color: #FFF9C4 !important; /* Amarillo Claro suave */
        border: 2px solid #FFFFFF !important; 
        border-radius: 40px 0 0 40px !important;
    }
    #search-icon-legacy {
        background-color: #FFF9C4 !important;
        border: 2px solid #FFFFFF !important;
        border-radius: 0 40px 40px 0 !important;
    }
    input#search {
        color: #000000 !important;
        font-family: 'Lucida Handwriting', 'Corsiva Hebrew', 'Georgia', cursive !important;
        font-style: italic !important;
    }
    #search-icon-legacy svg path, #search-icon-legacy yt-icon {
        fill: #000000 !important;
        color: #000000 !important;
    }

    /* 3. MARCOS REFORZADOS DE LÍNEAS AMARILLAS CLARO ALREDEDOR DE LOS VIDEOS */
    /* Este bloque ataca directamente a los contenedores de las miniaturas de los videos */
    ytd-rich-grid-media, 
    ytd-compact-video-renderer, 
    ytd-grid-video-renderer,
    ytd-video-renderer,
    #dismissible.ytd-rich-grid-media,
    .style-scope.ytd-rich-grid-media,
    ytd-thumbnail a {
        border: 3px dashed #FFF9C4 !important; /* Líneas de guiones amarillo claro */
        border-radius: 14px !important;
        box-shadow: 3px 3px 10px rgba(0,0,0,0.15) !important;
    }

    /* Ajuste para que las cajitas de los videos se separen bien y tengan un fondo translúcido tierno */
    ytd-rich-item-renderer, ytd-compact-video-renderer {
        background-color: rgba(230, 0, 35, 0.5) !important; /* Rojo transparente dentro del marco */
        padding: 10px !important;
        border-radius: 16px !important;
        margin-bottom: 15px !important;
    }

    /* 4. TODAS LAS LETRAS EN CURSIVA NEGRA CON DELINEADO BLANCO FANTASÍA */
    #video-title, 
    #channel-name, 
    #content-text, 
    span, 
    a, 
    h1, 
    h2, 
    h3, 
    #title,
    #description-text,
    yt-formatted-string,
    .ytd-comment-renderer,
    #metadata-line span,
    #text-containeryt-formatted-string,
    .style-scope.ytd-video-renderer,
    #video-title-link,
    yt-attributed-string span,
    .yt-core-attributed-string,
    #video-title.ytd-compact-video-renderer {
        color: #000000 !important;
        font-family: 'Lucida Handwriting', 'Corsiva Hebrew', 'Georgia', cursive !important;
        font-style: italic !important;
        background-color: transparent !important;
        background: transparent !important;
        text-shadow: -1px -1px 0 #FFFFFF, 1px -1px 0 #FFFFFF, -1px 1px 0 #FFFFFF, 1px 1px 0 #FFFFFF !important;
    }

    a:link, a:visited {
        color: #000000 !important;
    }

    /* 5. ICONOS GENERALES DE YOUTUBE: Blanco Puro */
    svg, path, yt-icon {
        fill: #FFFFFF !important;
        color: #FFFFFF !important;
    }
}
